def solve_neigh8(g):
    H,W=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cc=comps_all(g)
    out=[r[:] for r in g]
    # classify comps: keep if size>=2; singletons adopt nearest keeping-comp color (8-nbr dist <=1), else bg
    keep=[c for c in cc if len(c)>=2]
    singles=[c for c in cc if len(c)==1]
    for comp in singles:
        a,b=comp[0]
        cand=[]
        for Ck in keep:
            for k in Ck:
                d=max(abs(a-k[0]),abs(b-k[1]))
                if d<=1:
                    cand.append((d, out[k[0]][k[1]], k[0], k[1]))
        if cand:
            cand.sort()
            out[a][b]=cand[0][1]
        else:
            out[a][b]=bg
    return out

