    H,W=len(g),len(g[0])
    cc=comps_all(g)
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    sing=[c[0] for c in cc if len(c)==1]
    out=[r[:] for r in g]
    for a,b in sing:
        own=g[a][b]; cands=[]
        for comp in cc:
            if len(comp)<2 or g[comp[0][0]][comp[0][1]]==bg: continue
            for r_,c_ in comp:
                d=max(abs(a-r_),abs(b-c_))
                if d>2: break
            else:
                rs=[r for r,_ in comp]; cs=[c for _,c in comp]
                r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
                if d<=max(r1-a,c1-b) and (a,b) not in comp:
                    bbset={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}
                    # all comp cells in bb, and one missing cell is our singleton
                    if compcells := lambda:(len(set(comp))- (len(bbset)-1)):
                        pass
                    ok=all((r_,c_) in bbset for r_,c_ in comp)
                    if ok and (r1-r0+1)*(c1-c0+1)==len(comp)+1:
                        cands.append((d,g[r_][c_],(r1-r0+1)*(c1-c0+1)))
        if len(cands)==1: out[a][b]=cands[0][1]
